import { OrderStateType } from '../domain/OrderState';
import { OrderRepository } from '../domain/OrderRepository';
import { OrderResponse } from './dto/OrderResponse';

export class ListOrdersByStateUseCase {
  constructor(private orderRepository: OrderRepository) {}

  execute(state: any): OrderResponse[] {
    let stateStr = '';
    if (Array.isArray(state)) {
      stateStr = state[0]?.toString() || '';
    } else if (typeof state === 'string') {
      stateStr = state;
    }
    const orders = this.orderRepository.findByState(stateStr as OrderStateType);
    return orders.map(this.mapToResponse);
  }

  private mapToResponse(order: any): OrderResponse {
    return {
      id: order.id,
      state: order.getStateValue(),
      items: order.items.map((item: any) => ({
        productId: item.productId,
        quantity: item.quantity.value,
      })),
      createdAt: order.createdAt.toISOString(),
    };
  }
}

